<template><section class="pg-glide-bridge"><p v-if="!ready" role="status">独立 Studio 尚未就绪，请确认 localhost:5180 已启动。<button type="button" @click="reload">重试</button></p><iframe :key="generation" ref="frame" :src="'http://localhost:5180/?embed='+componentId" :title="componentId==='shredder'?'KfShredder 公共组件真实预览':componentId==='thoughtline'?'Thought Line preview':componentId==='folderfloat'?'Folder Float preview':componentId==='belltoggle'?'Bell Toggle preview':componentId==='holdbutton'?'Hold Button preview':componentId==='fusebutton'?'Fuse Button preview':componentId==='statusmark'?'Status Mark preview':componentId==='callchip'?'Call Chip preview':componentId==='linesidebar'?'Line Sidebar preview':componentId==='branchedmenu'?'Branched Menu preview':componentId==='texttype'?'Text Type 公共组件真实预览':componentId==='latticeloader'?'Lattice Loader 公共组件真实预览':componentId==='promptbar'?'Prompt Bar 公共组件真实预览':'Glide Select 公共组件真实预览'" @load="sync"/><p>唯一实现来自 {{componentId==='thoughtline'?'@beiluol/knowflow-ai':'@beiluol/knowflow-ui'}}；浮层位于独立预览视口内。</p></section></template>
<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue'
const props=withDefaults(defineProps<{settings?:Record<string,unknown>;componentId?:'shredder'|'swiperow'|'springcheck'|'glideselect'|'promptbar'|'latticeloader'|'texttype'|'branchedmenu'|'linesidebar'|'callchip'|'statusmark'|'fusebutton'|'holdbutton'|'belltoggle'|'folderfloat'|'thoughtline';events?:readonly string[]}>(),{settings:()=>({}),componentId:'glideselect',events:()=>['update:modelValue','change','open-change','select']});const emit=defineEmits<{event:[name:string,value:unknown]}>();const frame=ref<HTMLIFrameElement>(),ready=ref(false),generation=ref(0)
function sync(){frame.value?.contentWindow?.postMessage({type:props.componentId==='shredder'?'kf-shred-settings':props.componentId==='swiperow'?'kf-swipe-settings':props.componentId==='springcheck'?'kf-spring-settings':props.componentId==='thoughtline'?'kf-thought-settings':props.componentId==='folderfloat'?'kf-folder-settings':props.componentId==='belltoggle'?'kf-bell-settings':props.componentId==='holdbutton'?'kf-hold-settings':props.componentId==='fusebutton'?'kf-fuse-settings':props.componentId==='statusmark'?'kf-mark-settings':props.componentId==='callchip'?'kf-call-settings':props.componentId==='linesidebar'?'kf-line-settings':props.componentId==='branchedmenu'?'kf-branch-settings':props.componentId==='texttype'?'kf-text-settings':props.componentId==='latticeloader'?'kf-lattice-settings':props.componentId==='promptbar'?'kf-prompt-settings':'kf-glide-settings',settings:JSON.parse(JSON.stringify(props.settings)),storyId:new URLSearchParams(location.search).get('story')||'basic',theme:document.documentElement.dataset.theme||'light'},'http://localhost:5180')}
function receive(e:MessageEvent){if(e.origin!=='http://localhost:5180'||e.source!==frame.value?.contentWindow||e.data?.type!==(props.componentId==='shredder'?'kf-shred-event':props.componentId==='swiperow'?'kf-swipe-event':props.componentId==='springcheck'?'kf-spring-event':props.componentId==='thoughtline'?'kf-thought-event':props.componentId==='folderfloat'?'kf-folder-event':props.componentId==='belltoggle'?'kf-bell-event':props.componentId==='holdbutton'?'kf-hold-event':props.componentId==='fusebutton'?'kf-fuse-event':props.componentId==='statusmark'?'kf-mark-event':props.componentId==='callchip'?'kf-call-event':props.componentId==='linesidebar'?'kf-line-event':props.componentId==='branchedmenu'?'kf-branch-event':props.componentId==='texttype'?'kf-text-event':props.componentId==='latticeloader'?'kf-lattice-event':props.componentId==='promptbar'?'kf-prompt-event':'kf-glide-event')||e.data.version!==1)return;if(e.data.event==='ready'){ready.value=true;return}if(props.events.includes(e.data.event))emit('event',e.data.event,e.data.payload)}
function reload(){ready.value=false;generation.value++}
const observer=typeof MutationObserver!=='undefined'?new MutationObserver(sync):undefined
onMounted(()=>{window.addEventListener('message',receive);observer?.observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']})});onBeforeUnmount(()=>{window.removeEventListener('message',receive);observer?.disconnect()});watch(()=>props.settings,sync,{deep:true})
</script>
<style scoped>.pg-glide-bridge{width:100%;min-width:0}.pg-glide-bridge iframe{width:100%;height:680px;border:0;border-radius:var(--kf-radius-sm)}.pg-glide-bridge p{color:var(--kf-muted-foreground)}</style>
